import React, { useMemo } from 'react';
import { createPortal } from 'react-dom';
import Draggable from 'react-draggable';
import '../Css/drawpop.css';

function DrawPopup({ setDisplay, takeoff, drawingActive, onDrawingToggle }) {
  // ID único para vincular input + label (evita conflictos si hay varios popups)
  const switchId = useMemo(() => `drawSwitch-${Math.random().toString(36).slice(2)}`, []);

  return createPortal(
    <>
      {/* IMPORTANTÍSIMO: cancel evita que Draggable consuma el click del switch */}
      <Draggable cancel=".drawpopup-switch, .drawpopup-close">
        <div className="drawpopup-modal">
          <div className="modal-header">
            Information
          </div>

          <form className="modal-body" onSubmit={(e) => e.preventDefault()}>
            <div className="drawpopup-row">
              <label className="drawpopup-label">Name</label>
              <input
                className="drawpopup-input"
                type="text"
                value={takeoff?.template || ''}
                disabled
                readOnly
              />
            </div>

            <div className="drawpopup-row">
              <label className="drawpopup-label">Type</label>
              <input
                className="drawpopup-input"
                type="text"
                value={takeoff?.type || ''}
                disabled
                readOnly
              />
            </div>

            {/* Switch accesible + clickeable */}
            <div className="drawpopup-row" style={{ alignItems: 'center', gap: 8 }}>
              <label className="drawpopup-label" htmlFor={switchId}>Drawing</label>

              <span
                className="drawpopup-switch"
                // fallback: si el CSS bloquea el input, también toggleará por aquí
                onClick={() => onDrawingToggle(!drawingActive)}
                onMouseDown={(e) => e.stopPropagation()} // no iniciar drag
                role="switch"
                aria-checked={!!drawingActive}
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === ' ' || e.key === 'Enter') {
                    e.preventDefault();
                    onDrawingToggle(!drawingActive);
                  }
                }}
              >
                {/* OJO: debe quedar ANTES del .drawpopup-slider para que el selector
                   input:checked + .drawpopup-slider funcione con tu CSS */}
                <input
                  id={switchId}
                  type="checkbox"
                  checked={!!drawingActive}
                  onChange={(e) => onDrawingToggle(e.target.checked)}
                  // oculto pero accesible
                  style={{ position: 'absolute', opacity: 0, width: 0, height: 0 }}
                />
                {/* El label hace clic sobre el input aunque esté oculto */}
                <label htmlFor={switchId} className="drawpopup-slider" />
              </span>
            </div>
          </form>
        </div>
      </Draggable>
    </>,
    document.getElementById('root')
  );
}

export default DrawPopup;
