import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { projectId } from "../Constants";
import { routes } from "../Constants";
import CoursePopup from "./CoursePopup";
import EditCoursePopup from "./EditCoursePopup";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../database/db";
import { toast } from "react-toastify";
import useSignal from "../hooks/signals";
import Dexie from "dexie";
import "../Css/lengthpop.css";
import DrawPopup from "./DrawPopup";
import ProcessingOverlay from "./ProcessingOverlay";

function PerimeterPopupDraw({ setDisplay, current_data=null }) {

  const [active, setActive] = useState('')
  const [lineTemplate, setLineTemplate] = useState([]);
  const signal = useSignal();
  const [openDrawPopup, setOpenDrawPopup] = useState(false);
  const [dataTakeoff, setDataTakeoff] = useState();
  const [isDrawing, setIsDrawing] = useState(false);
  const [lineColor, setLineColor] = useState("#000000");
  const [loading, setLoading] = useState(true);

  const [formData, setFormData] = useState({


    lineTemplate: "",
    takeoff_name: "",

  });

  var dB = new Dexie('takeoff');
  dB.version(1).stores({
    measurements: 'takeoff, name',
  });

  useEffect(() => {
  if (current_data) {
    setFormData((prev) => ({
      ...prev,
      lineTemplate: typeof current_data === "string" 
                    ? current_data 
                    : JSON.stringify(current_data),
    }));
  }
}, [current_data]);


  useEffect(() => {
    if (active !== '') {
      try {
        console.log(formData.takeoff_name);
        signal.emit('takeoff', { 
          ...active, 
          openPopup: true, 
          template: formData.takeoff_name,
          color: lineColor 
        });
      } catch (e) {
        console.log(e)
      }
    }
  }, [active, signal, lineColor])


  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        let url = `${routes.templates}?type_template=perimeter`;
        let response = await fetch(url, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
          },
        });
        let data = await response.json();
        //   console.log("checking response data", data.template);
        setLineTemplate(data.template);
      } catch (error) {
        console.error("Error cargando templates:", error);
        toast.error("Error loading templates");
      } finally {
        setLoading(false); // ocultar overlay
      }
    })();
  }, []);

  const handleDrawingToggle = (active) => {
    setIsDrawing(active);
    if (!active) {
      // Aquí cancelas el modo dibujo, por ejemplo
      setOpenDrawPopup(false);  // Cierra popup cuando se desactiva
      setActive('');            // Limpia estado para parar dibujo
      signal.emit('takeoff', { type: '' });  // Indica a otros que desactiven modo
    }
  };

  const handleSaveTemplate = async () => {

     dB.open();
    const dbData =  dB.measurements.toArray();
    if (dbData) {
       dB.measurements.clear();
    }

    const lengthName = formData.takeoff_name;
    const lineTemplate = formData.lineTemplate;
    dB.open();
    const data = {
                    type: 'perimeter',
                    template: JSON.parse(lineTemplate).template_name,
                };
    setDataTakeoff(data);
    /*setOpenDrawPopup(true);

    dB.measurements.add({ name: lengthName, takeoff: 'length' , lineTemplate: lineTemplate});
    setActive({ type: 'length' });
    await  dB.measurements.add({ name: lengthName, takeoff: 'length_old', lineTemplate: lineTemplate });
    //setDisplay(false);*/

    //setOpenDrawPopup(true);
    setIsDrawing(true);

    await dB.measurements.add({ 
        name: lengthName, 
        takeoff: 'perimeter', 
        lineTemplate: lineTemplate 
    });
    setActive({ type: 'perimeter' });
    await  dB.measurements.add({ name: lengthName, takeoff: 'perimeter_old', lineTemplate: lineTemplate });
    setDisplay(false);


  };
  const handleInputChange = (event) => {
    const { name, value } = event.target;

    localStorage.setItem(name, value);
    setFormData({
      ...formData,
      [name]: value,
    });
   // console.log(formData);
  }


  return (
    <>
      <ProcessingOverlay visible={loading} message="Processing Templates..." />
      {createPortal(
        <Draggable>
          <div className="popup__count popup-length-takeoffDraw">
            <div className="modal-header">
              perimeter Takeoff
              <span
                className="close-btn"
                onClick={() => {
                  setDisplay(false);
                }}
              >
                &times;
              </span>
            </div>
            <form className="modal-body">
              <div className="takeoff-name-mainDraw">
                <div className="takeoff-nameDraw">
                  <label className="label">Select Template</label>
                  <select
                    className="border-blue"
                    name="lineTemplate"
                    value={formData.lineTemplate}
                    onChange={handleInputChange}
                    
                  >
                    <option value="" hidden="">
                      -- Select template --
                    </option>
                    {lineTemplate.map((template) => (
                      <option
                        key={template.id}
                        value={JSON.stringify(template)}
                      >
                        {template.template_name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="takeoff-nameDraw">
                  <label className="label">TakeOff Name</label>
                  <input
                    className="border-blue"
                    type="text"
                    name="takeoff_name"
                    value={formData.takeoff_name}
                    onChange={handleInputChange}
                  />
                </div>

                {/* 🎨 Selector de color */}
                <div className="takeoff-nameDraw">
                  <label className="label">Line Color</label>
                  <select
                    className="border-blue"
                    value={lineColor}
                    onChange={(e) => setLineColor(e.target.value)}
                    //style={{ width: "120px", height: "30px" }} // opcional: ajustar tamaño
                  >
                    {[
                      { hex: "#000000", name: "Black" },
                      { hex: "#ff0000", name: "Red" },
                      { hex: "#00ff00", name: "Green" },
                      { hex: "#0000ff", name: "Blue" },
                      { hex: "#ffa500", name: "Orange" },
                      { hex: "#800080", name: "Purple" },
                      { hex: "#ffff00", name: "Yellow" },
                      { hex: "#00ffff", name: "Cyan" },
                      { hex: "#808080", name: "Gray" },
                      { hex: "#e22b88", name: "Pink" },
                      { hex: "#008000", name: "Dark Green" },
                      { hex: "#ff1493", name: "Deep Pink" },
                      { hex: "#1e90ff", name: "Dodger Blue" },
                    ].map((color) => (
                      <option
                        key={color.hex}
                        value={color.hex}
                        style={{
                          backgroundColor: color.hex,
                          color: ["#ffff00", "#00ff00", "#00ffff"].includes(color.hex)
                            ? "#000" // texto negro si el fondo es claro
                            : "#fff", // texto blanco si es oscuro
                          fontWeight: "bold",
                        }}
                      >
                        {color.name}
                      </option>
                    ))}
                  </select>
                </div>

              </div>


              <button
                className="btn-save mt-2"
                onClick={handleSaveTemplate}
                type="button"
              >
                Start TakeOff
              </button>
            </form>
          </div>
        </Draggable>,
        document.querySelector("#root")
      )}
      {openDrawPopup && (
                <DrawPopup
                  takeoff={dataTakeoff}
                  setDisplay={setOpenDrawPopup}
                  drawingActive={isDrawing}
                  onDrawingToggle={handleDrawingToggle}  // Pasa función para manejar toggle
                />
            )}

    </>
  );
}

export default PerimeterPopupDraw;
