import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";

pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

export default function PageSelectorPopup({ file, onClose, onSave }) {
  const [numPages, setNumPages] = useState(null);
  const [selectedPages, setSelectedPages] = useState([]);
  const [pageMeta, setPageMeta] = useState([]);
  const [scanning, setScanning] = useState(false);

  const togglePage = (page) => {
    setSelectedPages((prev) =>
      prev.includes(page) ? prev.filter((p) => p !== page) : [...prev, page]
    );
  };

  const selectAll = () => {
    if (selectedPages.length === numPages) setSelectedPages([]);
    else setSelectedPages(Array.from({ length: numPages }, (_, i) => i + 1));
  };

  // Agrupa texto por líneas
  const itemsToLines = (items) => {
    const lines = [];
    let currentY = null;
    let buffer = [];
    for (const it of items) {
      const y = Math.round(it.transform?.[5] ?? 0);
      if (currentY === null) {
        currentY = y;
        buffer.push(it.str);
      } else if (Math.abs(y - currentY) <= 2) {
        buffer.push(it.str);
      } else {
        lines.push(buffer.join(" ").trim());
        buffer = [it.str];
        currentY = y;
      }
    }
    if (buffer.length) lines.push(buffer.join(" ").trim());
    return lines;
  };

  // Escanear PDF buscando códigos
  useEffect(() => {
    let cancelled = false;
    const scan = async () => {
      if (!file?.url) return;
      setScanning(true);
      try {
        const task = pdfjs.getDocument(file.url);
        const pdf = await task.promise;
        const meta = [];
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const tc = await page.getTextContent();
          const lines = itemsToLines(tc.items);

          // Regex universal para detectar códigos
          const regex = /\b([A-Z]{1,4}[-.]?\d{1,4})\b/g;
          const codes = [];
          const joined = lines.join("\n");
          let m;
          while ((m = regex.exec(joined)) !== null) {
            const code = m[1];
            if (!codes.includes(code)) codes.push(code);
          }
          meta.push({ page: i, codes });
          if (cancelled) break;
        }
        if (!cancelled) setPageMeta(meta);
      } catch (e) {
        console.error("Error escaneando PDF:", e);
      } finally {
        if (!cancelled) setScanning(false);
      }
    };
    scan();
    return () => {
      cancelled = true;
    };
  }, [file]);

  const getCodesFor = (page) =>
    pageMeta.find((p) => p.page === page)?.codes ?? [];

  return createPortal(
    <Draggable handle=".modal-header">
      <div
        className="popup__count"
        style={{
          zIndex: 99999,
          position: "fixed",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "90%",
          maxWidth: "1000px",
          background: "#fff",
          borderRadius: "8px",
          boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
          overflow: "hidden",
        }}
      >
        {/* HEADER */}
        <div
          className="modal-header"
          style={{
            background: "#343a40",
            color: "#fff",
            cursor: "move",
            padding: "10px 15px",
            fontWeight: "bold",
          }}
        >
          Seleccionar páginas — {file.name}
          <span
            onClick={onClose}
            style={{
              cursor: "pointer",
              float: "right",
              fontSize: "18px",
              fontWeight: "bold",
            }}
          >
            ×
          </span>
        </div>

        {/* BODY */}
        <div
          className="modal-body"
          style={{
            maxHeight: "70vh",
            overflowY: "auto",
            background: "#f8f9fa",
            padding: "15px",
          }}
        >
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <button
              onClick={selectAll}
              style={{
                background: "transparent",
                border: "1px solid #0d6efd",
                color: "#0d6efd",
                padding: "6px 12px",
                borderRadius: "4px",
                cursor: "pointer",
                marginBottom: "10px",
              }}
            >
              {selectedPages.length === numPages
                ? "Deseleccionar todas"
                : "Seleccionar todas"}
            </button>
            {scanning && (
              <span style={{ fontSize: 12, color: "#6c757d" }}>
                Analizando páginas para detectar códigos…
              </span>
            )}
          </div>

          <Document
            file={file.url}
            onLoadSuccess={({ numPages }) => setNumPages(numPages)}
            loading={<p>Cargando PDF...</p>}
          >
            {Array.from(new Array(numPages), (el, index) => {
              const pageNo = index + 1;
              const codes = getCodesFor(pageNo);
              return (
                <div
                  key={`page_${pageNo}`}
                  style={{
                    display: "inline-block",
                    margin: "10px",
                    textAlign: "center",
                    border: selectedPages.includes(pageNo)
                      ? "2px solid #0d6efd"
                      : "1px solid #ccc",
                    borderRadius: "8px",
                    background: "#fff",
                    padding: "6px",
                    width: 180,
                  }}
                >
                  <Page
                    pageNumber={pageNo}
                    width={150}
                    renderTextLayer={false}
                    renderAnnotationLayer={false}
                  />

                  {/* Checkbox página */}
                  <label style={{ fontSize: "12px", display: "block", marginTop: 6 }}>
                    <input
                      type="checkbox"
                      checked={selectedPages.includes(pageNo)}
                      onChange={() => togglePage(pageNo)}
                      style={{ marginRight: "4px" }}
                    />
                    Página {pageNo}
                  </label>

                  {/* Solo nombre del archivo + código */}
                  {codes.length > 0 ? (
                    <div
                      style={{
                        marginTop: 6,
                        fontSize: 11,
                        textAlign: "left",
                        background: "#f8f9fa",
                        border: "1px dashed #ced4da",
                        borderRadius: 6,
                        padding: "6px",
                        maxHeight: 90,
                        overflowY: "auto",
                      }}
                      title={codes.join(", ")}
                    >
                      <div style={{ lineHeight: 1.25 }}>
                        <strong>{file.name.split("/").pop()}</strong>
                        {codes.map((code, i) => (
                          <div key={i}>— {code}</div>
                          
                        ))}
                      </div>
                    </div>
                  ) : (
                    <div style={{ marginTop: 6, fontSize: 11, color: "#6c757d" }}>
                      (Sin código detectado)
                    </div>
                  )}
                </div>
              );
            })}
          </Document>
        </div>

        {/* FOOTER */}
        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            gap: "10px",
            background: "#f1f1f1",
            borderTop: "1px solid #ccc",
            padding: "10px 15px",
          }}
        >
          <button
            onClick={onClose}
            style={{
              background: "#6c757d",
              border: "none",
              color: "#fff",
              padding: "6px 12px",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Cancelar
          </button>
          <button
            onClick={() => onSave(selectedPages)}
            style={{
              background: "#0d6efd",
              border: "none",
              color: "#fff",
              padding: "6px 12px",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Guardar ({selectedPages.length})
          </button>
        </div>
      </div>
    </Draggable>,
    document.getElementById("root")
  );
}
